/**
 * PreviewAnswerControl tests (#1284) — the respondent-side control for each of
 * the proto's canonical 10 `QuestionType`s.
 *
 * These controls are GENUINELY INTERACTIVE, which is the whole difference from
 * `editor/QuestionAnswerPreview.tsx`'s deliberately inert shapes. So the
 * coverage that matters is: does each type render a real, correctly-roled
 * control, and does interacting with it report the right answer shape back.
 */

import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { PreviewAnswerControl } from "../PreviewAnswerControl";
import { initialAnswer } from "../../../lib/previewAnswers";
import type { PreviewAnswer } from "../../../lib/previewAnswers";
import type { QuestionDTO, QuestionType } from "../../../api/questions";

// Held in constants, not written inline: `react/jsx-no-literals` (noStrings)
// is the i18n leak guard, and it flags a bare string child even in a test.
const ERROR_TEXT = "bad";

function question(
  type: QuestionType,
  overrides: Partial<QuestionDTO> = {},
): QuestionDTO {
  return {
    id: "q1",
    questionType: type,
    prompt: "How was it?",
    position: 0,
    required: false,
    config: {},
    branches: [],
    ...overrides,
  };
}

function renderControl(
  q: QuestionDTO,
  answer: PreviewAnswer = initialAnswer(q),
  opts: { invalid?: boolean } = {},
) {
  const onChange = vi.fn();
  render(
    <>
      <span id="prompt">{q.prompt}</span>
      <PreviewAnswerControl
        question={q}
        answer={answer}
        onChange={onChange}
        labelledBy="prompt"
        errorId={opts.invalid === true ? "err" : undefined}
        invalid={opts.invalid ?? false}
      />
      <span id="err">{ERROR_TEXT}</span>
    </>,
  );
  return onChange;
}

describe("PreviewAnswerControl — single_select / yes_no / true_false", () => {
  const q = question("single_select", { config: { options: ["Good", "Bad"] } });

  it("renders a radiogroup with one radio per option", () => {
    renderControl(q);

    expect(screen.getByRole("radiogroup")).toBeInTheDocument();
    expect(screen.getAllByRole("radio")).toHaveLength(2);
  });

  it("shows the select-one hint", () => {
    renderControl(q);
    expect(
      screen.getByText(m.ask_survey_preview_select_one_hint()),
    ).toBeInTheDocument();
  });

  it("reports the chosen option", async () => {
    const onChange = renderControl(q);

    await userEvent.click(screen.getByRole("radio", { name: "Bad" }));

    expect(onChange).toHaveBeenCalledWith({ kind: "choice", choice: "Bad" });
  });

  it("reflects the current choice", () => {
    renderControl(q, { kind: "choice", choice: "Good" });
    expect(screen.getByRole("radio", { name: "Good" })).toBeChecked();
  });

  it.each(["yes_no", "true_false"] as const)(
    "renders %s as a radiogroup from its seeded options",
    (type) => {
      renderControl(question(type));
      expect(screen.getByRole("radiogroup")).toBeInTheDocument();
      expect(screen.getAllByRole("radio")).toHaveLength(2);
    },
  );
});

describe("PreviewAnswerControl — multiple_select", () => {
  const q = question("multiple_select", {
    config: { options: ["A", "B", "C"] },
  });

  it("renders a checkbox per option with the select-many hint", () => {
    renderControl(q);

    expect(screen.getAllByRole("checkbox")).toHaveLength(3);
    expect(
      screen.getByText(m.ask_survey_preview_select_many_hint()),
    ).toBeInTheDocument();
  });

  it("adds a checked option", async () => {
    const onChange = renderControl(q);

    await userEvent.click(screen.getByRole("checkbox", { name: "B" }));

    expect(onChange).toHaveBeenCalledWith({ kind: "choices", choices: ["B"] });
  });

  it("keeps the AUTHORED order rather than click order", async () => {
    const onChange = renderControl(q, { kind: "choices", choices: ["C"] });

    await userEvent.click(screen.getByRole("checkbox", { name: "A" }));

    expect(onChange).toHaveBeenCalledWith({ kind: "choices", choices: ["A", "C"] });
  });

  it("removes an already-checked option", async () => {
    const onChange = renderControl(q, { kind: "choices", choices: ["A", "B"] });

    await userEvent.click(screen.getByRole("checkbox", { name: "A" }));

    expect(onChange).toHaveBeenCalledWith({ kind: "choices", choices: ["B"] });
  });
});

describe("PreviewAnswerControl — scale", () => {
  const q = question("scale", {
    config: {
      scale_min: 1,
      scale_max: 5,
      scale_min_label: "Poor",
      scale_max_label: "Great",
    },
  });

  it("renders one radio per stop", () => {
    renderControl(q);
    expect(screen.getAllByRole("radio")).toHaveLength(5);
  });

  it("renders the end labels", () => {
    renderControl(q);
    expect(screen.getByText("Poor")).toBeInTheDocument();
    expect(screen.getByText("Great")).toBeInTheDocument();
  });

  it("omits the label row entirely when neither end is labelled", () => {
    renderControl(question("scale", { config: { scale_min: 1, scale_max: 3 } }));
    expect(screen.queryByText("Poor")).not.toBeInTheDocument();
  });

  it("reports the chosen stop as a number, not a string", async () => {
    const onChange = renderControl(q);

    await userEvent.click(screen.getByRole("radio", { name: "3" }));

    expect(onChange).toHaveBeenCalledWith({ kind: "scale", scale: 3 });
  });

  it("keeps the native radios focusable so arrow keys work", () => {
    // Transparent rather than `hidden`: a hidden input leaves the tab order and
    // the group stops being keyboard-navigable.
    renderControl(q);

    const radio = screen.getByRole("radio", { name: "3" });
    expect(radio).not.toHaveAttribute("hidden");
    expect(radio.className).toContain("opacity-0");
  });

  it("confines each radio to its OWN tile — the blank-screen regression", () => {
    // The radio must be absolutely positioned against its own label, not
    // `sr-only`. `sr-only` is `position:absolute` with a -1px margin, and the
    // label was not a positioned ancestor, so the input resolved against a
    // distant one. Clicking a tile focuses the input, the browser scrolls the
    // focused element into view, and the preview's `overflow-y-auto` container
    // jumped to that stray coordinate — the page looked blank.
    //
    // Asserted at the CLASS level on purpose: jsdom has no layout engine and
    // never scrolls, so no rendering assertion can catch this. That is exactly
    // why it reached a browser undetected.
    renderControl(q);

    const radio = screen.getByRole("radio", { name: "3" });
    expect(radio.className).not.toContain("sr-only");
    expect(radio.className).toContain("absolute");
    expect(radio.className).toContain("inset-cog-0");

    const tile = radio.closest("label");
    expect(tile, "the radio must live inside its tile").not.toBeNull();
    expect(
      tile?.className,
      "the tile must be the positioned ancestor, or inset-cog-0 escapes it",
    ).toContain("relative");
  });

  it("shows a focus ring on the tile, since the input itself is transparent", () => {
    renderControl(q);

    // `has-[:focus-visible]`, not `peer-focus-visible` — the label is the
    // input's PARENT, and `peer-*` only styles a peer's SIBLING, so a peer
    // variant here would compile to a selector that never matches.
    const tile = screen.getByRole("radio", { name: "3" }).closest("label");
    expect(tile?.className).toContain("has-[:focus-visible]:outline");
    expect(tile?.className).not.toContain("peer-focus-visible");
  });

  it("supports a 0-based scale, so 0 is selectable", async () => {
    const onChange = renderControl(
      question("scale", { config: { scale_min: 0, scale_max: 2 } }),
    );

    await userEvent.click(screen.getByRole("radio", { name: "0" }));

    expect(onChange).toHaveBeenCalledWith({ kind: "scale", scale: 0 });
  });
});

describe("PreviewAnswerControl — rank_order", () => {
  it("renders the rank list and reports a reorder", async () => {
    const q = question("rank_order", { config: { options: ["A", "B"] } });
    const onChange = renderControl(q);

    await userEvent.click(
      screen.getByRole("button", {
        name: m.ask_survey_preview_rank_move_up({ item: "B" }),
      }),
    );

    expect(onChange).toHaveBeenCalledWith({ kind: "ranking", ranking: ["B", "A"] });
  });
});

describe("PreviewAnswerControl — matrix", () => {
  const q = question("matrix", {
    config: {
      matrix_rows: ["Speed"],
      matrix_columns: ["Low", "High"],
    },
  });

  it("renders the grid and REPLACES the row's selection for a single-select matrix", async () => {
    const onChange = renderControl(q, {
      kind: "matrix",
      matrix: { Speed: ["Low"] },
    });

    await userEvent.click(
      screen.getByRole("radio", {
        name: m.ask_survey_editor_cfg_matrix_cell_aria({
          row: "Speed",
          column: "High",
        }),
      }),
    );

    expect(onChange).toHaveBeenCalledWith({
      kind: "matrix",
      matrix: { Speed: ["High"] },
    });
  });

  it("toggles within the row when multiple selections are allowed", async () => {
    const multi = question("matrix", {
      config: {
        matrix_rows: ["Speed"],
        matrix_columns: ["Low", "High"],
        matrix_allow_multiple: true,
      },
    });
    const onChange = renderControl(multi, {
      kind: "matrix",
      matrix: { Speed: ["Low"] },
    });

    await userEvent.click(
      screen.getByRole("checkbox", {
        name: m.ask_survey_editor_cfg_matrix_cell_aria({
          row: "Speed",
          column: "High",
        }),
      }),
    );

    expect(onChange).toHaveBeenCalledWith({
      kind: "matrix",
      matrix: { Speed: ["Low", "High"] },
    });
  });
});

describe("PreviewAnswerControl — free_text", () => {
  it("renders a textarea with the respondent-facing default placeholder", () => {
    renderControl(question("free_text"));

    const field = screen.getByRole("textbox");
    expect(field.tagName).toBe("TEXTAREA");
    // Not the editor's third-person "Respondent types their answer…", which
    // would read oddly TO the respondent.
    expect(field).toHaveAttribute(
      "placeholder",
      m.ask_survey_preview_text_placeholder(),
    );
  });

  it("prefers an author-configured placeholder", () => {
    renderControl(
      question("free_text", { config: { placeholder: "Tell us more" } }),
    );

    expect(screen.getByRole("textbox")).toHaveAttribute(
      "placeholder",
      "Tell us more",
    );
  });

  it("reports typed text", async () => {
    const onChange = renderControl(question("free_text"));

    await userEvent.type(screen.getByRole("textbox"), "h");

    expect(onChange).toHaveBeenCalledWith({ kind: "text", text: "h" });
  });

  it("marks itself invalid and points at the error", () => {
    renderControl(question("free_text"), undefined, { invalid: true });

    const field = screen.getByRole("textbox");
    expect(field).toHaveAttribute("aria-invalid", "true");
    expect(field).toHaveAttribute("aria-describedby", "err");
  });

  it("falls back to a textarea for an unrecognized question type", () => {
    // normalizeQuestion yields "unspecified" for an unknown wire value —
    // collecting something beats rendering an unanswerable blank.
    renderControl(question("unspecified"));
    expect(screen.getByRole("textbox")).toBeInTheDocument();
  });
});

describe("PreviewAnswerControl — date", () => {
  it("renders a native date input carrying the configured bounds", () => {
    renderControl(
      question("date", { config: { date_min: "2026-01-01", date_max: "2026-12-31" } }),
    );

    const field = screen.getByLabelText("How was it?");
    expect(field).toHaveAttribute("type", "date");
    expect(field).toHaveAttribute("min", "2026-01-01");
    expect(field).toHaveAttribute("max", "2026-12-31");
  });

  it("omits empty bounds rather than setting min=''", () => {
    renderControl(question("date", { config: { date_min: "", date_max: "" } }));

    const field = screen.getByLabelText("How was it?");
    expect(field).not.toHaveAttribute("min");
    expect(field).not.toHaveAttribute("max");
  });
});

describe("PreviewAnswerControl — number", () => {
  it("renders type=text + inputMode=numeric, not a native number input", () => {
    // Divergence 8: a native number input's spinner and its silent clearing of
    // an intermediate value ("-", "1.") destroy in-progress entry.
    renderControl(question("number"));

    const field = screen.getByRole("textbox");
    expect(field).toHaveAttribute("type", "text");
    expect(field).toHaveAttribute("inputmode", "numeric");
  });

  it("reports typed digits", async () => {
    const onChange = renderControl(question("number"));

    await userEvent.type(screen.getByRole("textbox"), "7");

    expect(onChange).toHaveBeenCalledWith({ kind: "text", text: "7" });
  });

  it("does NOT set range-widget ARIA on a textbox", () => {
    // aria-valuemin/aria-valuemax are spinbutton/slider attributes. On this
    // control's implicit `textbox` role assistive tech drops them and axe flags
    // them, so setting them described an effect that never happened. The bounds
    // reach the respondent through help text and validateAnswer's message.
    renderControl(question("number", { config: { number_min: 1, number_max: 9 } }));

    const field = screen.getByRole("textbox");
    expect(field).not.toHaveAttribute("aria-valuemin");
    expect(field).not.toHaveAttribute("aria-valuemax");
  });
});

describe("PreviewAnswerControl — defensive fallbacks", () => {
  // Every control narrows the answer union before reading it, because the answer
  // map and the question list are separate state: a question whose TYPE changed
  // in the editor while a preview was open would otherwise be handed an answer
  // of the wrong shape. Each control must degrade to "unanswered" rather than
  // throw on a property the union member does not have.

  it("renders an unselected radiogroup when handed the wrong answer kind", () => {
    renderControl(
      question("single_select", { config: { options: ["A", "B"] } }),
      { kind: "text", text: "stale" },
    );

    for (const radio of screen.getAllByRole("radio")) {
      expect(radio).not.toBeChecked();
    }
  });

  it("renders an unchecked checkbox group when handed the wrong answer kind", () => {
    renderControl(question("multiple_select", { config: { options: ["A"] } }), {
      kind: "text",
      text: "stale",
    });

    expect(screen.getByRole("checkbox")).not.toBeChecked();
  });

  it("renders an unselected scale when handed the wrong answer kind", () => {
    renderControl(question("scale", { config: { scale_min: 1, scale_max: 3 } }), {
      kind: "text",
      text: "stale",
    });

    for (const radio of screen.getAllByRole("radio")) {
      expect(radio).not.toBeChecked();
    }
  });

  it("renders an empty ranking when handed the wrong answer kind", () => {
    renderControl(question("rank_order", { config: { options: ["A", "B"] } }), {
      kind: "text",
      text: "stale",
    });

    expect(screen.queryAllByRole("listitem")).toHaveLength(0);
  });

  it("renders an empty matrix selection when handed the wrong answer kind", () => {
    renderControl(
      question("matrix", {
        config: { matrix_rows: ["Speed"], matrix_columns: ["Low", "High"] },
      }),
      { kind: "text", text: "stale" },
    );

    for (const radio of screen.getAllByRole("radio")) {
      expect(radio).not.toBeChecked();
    }
  });

  it("still records a matrix click when the prior answer was the wrong kind", async () => {
    const onChange = renderControl(
      question("matrix", {
        config: { matrix_rows: ["Speed"], matrix_columns: ["Low"] },
      }),
      { kind: "choice", choice: "stale" },
    );

    await userEvent.click(
      screen.getByRole("radio", {
        name: m.ask_survey_editor_cfg_matrix_cell_aria({
          row: "Speed",
          column: "Low",
        }),
      }),
    );

    expect(onChange).toHaveBeenCalledWith({
      kind: "matrix",
      matrix: { Speed: ["Low"] },
    });
  });

  it("renders an empty textarea when handed the wrong answer kind", () => {
    renderControl(question("free_text"), { kind: "scale", scale: 3 });
    expect(screen.getByRole("textbox")).toHaveValue("");
  });

  it("renders an empty date field when handed the wrong answer kind", () => {
    renderControl(question("date"), { kind: "scale", scale: 3 });
    expect(screen.getByLabelText("How was it?")).toHaveValue("");
  });

  it("renders an empty number field when handed the wrong answer kind", () => {
    renderControl(question("number"), { kind: "scale", scale: 3 });
    expect(screen.getByRole("textbox")).toHaveValue("");
  });
});

describe("PreviewAnswerControl — partial configuration", () => {
  it("renders only the low scale label when the high one is unset", () => {
    renderControl(
      question("scale", {
        config: { scale_min: 1, scale_max: 3, scale_min_label: "Poor" },
      }),
    );

    expect(screen.getByText("Poor")).toBeInTheDocument();
  });

  it("renders only the high scale label when the low one is unset", () => {
    renderControl(
      question("scale", {
        config: { scale_min: 1, scale_max: 3, scale_max_label: "Great" },
      }),
    );

    expect(screen.getByText("Great")).toBeInTheDocument();
  });

  it("omits date bounds entirely when the question configures none", () => {
    renderControl(question("date"));

    const field = screen.getByLabelText("How was it?");
    expect(field).not.toHaveAttribute("min");
    expect(field).not.toHaveAttribute("max");
  });

  it("applies only the configured end of a one-sided date bound", () => {
    renderControl(question("date", { config: { date_min: "2026-01-01" } }));

    const field = screen.getByLabelText("How was it?");
    expect(field).toHaveAttribute("min", "2026-01-01");
    expect(field).not.toHaveAttribute("max");
  });

  it("keeps inputMode numeric so mobile shows a number keypad", () => {
    renderControl(question("number"));
    expect(screen.getByRole("textbox")).toHaveAttribute("inputmode", "numeric");
  });

  it("falls back to the default placeholder for an empty configured placeholder", () => {
    renderControl(question("free_text", { config: { placeholder: "" } }));

    expect(screen.getByRole("textbox")).toHaveAttribute(
      "placeholder",
      m.ask_survey_preview_text_placeholder(),
    );
  });
});


describe("PreviewAnswerControl — scale group labelling", () => {
  it("announces BOTH the prompt and the range via aria-labelledby", () => {
    // An `aria-label` alongside `aria-labelledby` is dead weight — labelledby
    // wins — so the range string and its 11 translations were unreachable
    // before this. Both ids must resolve to real elements.
    renderControl(
      question("scale", { config: { scale_min: 1, scale_max: 5 } }),
    );

    const group = screen.getByRole("radiogroup");
    expect(group).not.toHaveAttribute("aria-label");

    const ids = (group.getAttribute("aria-labelledby") ?? "").split(" ").filter(Boolean);
    expect(ids).toHaveLength(2);
    const texts = ids.map((id) => document.getElementById(id)?.textContent ?? "");
    expect(texts.some((t) => t.includes("How was it?"))).toBe(true);
    expect(
      texts.some(
        (t) => t === m.ask_survey_preview_scale_group_label({ min: 1, max: 5 }),
      ),
    ).toBe(true);
  });
});


