/**
 * Keyboard operability of the respondent preview, per question type (#1284).
 *
 * This exists as its own file because the property under test cuts ACROSS the
 * per-component tests: "a respondent using only a keyboard can answer every
 * answerable question type". The bug that prompted it was reported per-type
 * ("multiple select, ranking, matrix and date don't respond to Enter"), and the
 * causes turned out to be different in each case — a missing Enter affordance on
 * the choice inputs, and focus being dropped entirely after a rank reorder — so
 * a single table-driven sweep is what keeps a future regression in any one type
 * from hiding.
 *
 * Space is asserted alongside Enter throughout. Space is the NATIVE activation
 * key for both roles, and the Enter affordance is layered on top of it; a change
 * that made Enter work by breaking Space would be a downgrade for every
 * respondent who already knows the platform convention.
 */

import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { useState } from "react";
import { describe, expect, it, vi } from "vitest";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { PreviewAnswerControl } from "../PreviewAnswerControl";
import { initialAnswer, type PreviewAnswer } from "../../../lib/previewAnswers";
import type { QuestionDTO, QuestionType } from "../../../api/questions";

const OPTIONS = { options: ["Alpha", "Beta", "Gamma"] };
const MATRIX = { matrix_rows: ["R1", "R2"], matrix_columns: ["C1", "C2"] };

function question(
  type: QuestionType,
  config: Record<string, unknown> = {},
): QuestionDTO {
  return {
    id: "q1",
    questionType: type,
    prompt: "How was it?",
    position: 0,
    required: false,
    branches: [],
    config: config as QuestionDTO["config"],
  };
}

function renderControl(q: QuestionDTO, answer: PreviewAnswer = initialAnswer(q)) {
  const onChange = vi.fn();
  render(
    <>
      <span id="prompt">{q.prompt}</span>
      <PreviewAnswerControl
        question={q}
        answer={answer}
        onChange={onChange}
        labelledBy="prompt"
        invalid={false}
      />
    </>,
  );
  return onChange;
}

/** The choice-shaped types: every one must answer to BOTH Enter and Space. */
const CHOICE_CASES: ReadonlyArray<{
  readonly label: string;
  readonly q: QuestionDTO;
  readonly expected: PreviewAnswer;
}> = [
  {
    label: "single_select",
    q: question("single_select", OPTIONS),
    expected: { kind: "choice", choice: "Alpha" },
  },
  {
    label: "yes_no",
    q: question("yes_no"),
    expected: { kind: "choice", choice: "Yes" },
  },
  {
    label: "multiple_select",
    q: question("multiple_select", OPTIONS),
    expected: { kind: "choices", choices: ["Alpha"] },
  },
  {
    label: "scale",
    q: question("scale", { scale_min: 1, scale_max: 5 }),
    expected: { kind: "scale", scale: 1 },
  },
];

describe("preview keyboard operability", () => {
  describe.each(CHOICE_CASES)("$label", ({ q, expected }) => {
    it("selects the focused choice with Enter", async () => {
      const onChange = renderControl(q);
      await userEvent.tab();
      await userEvent.keyboard("{Enter}");
      expect(onChange).toHaveBeenCalledWith(expected);
    });

    it("still selects with Space, the native key", async () => {
      const onChange = renderControl(q);
      await userEvent.tab();
      await userEvent.keyboard(" ");
      expect(onChange).toHaveBeenCalledWith(expected);
    });

    it("reaches the control by Tab alone", async () => {
      renderControl(q);
      await userEvent.tab();
      expect(document.activeElement?.tagName).toBe("INPUT");
    });
  });

  it("selects a matrix cell with Enter", async () => {
    const onChange = renderControl(question("matrix", MATRIX));
    await userEvent.tab();
    await userEvent.keyboard("{Enter}");
    expect(onChange).toHaveBeenCalledWith({
      kind: "matrix",
      matrix: { R1: ["C1"] },
    });
  });

  it("selects a multi-select matrix cell with Enter", async () => {
    const onChange = renderControl(
      question("matrix", { ...MATRIX, matrix_allow_multiple: true }),
    );
    await userEvent.tab();
    await userEvent.keyboard("{Enter}");
    expect(onChange).toHaveBeenCalledWith({
      kind: "matrix",
      matrix: { R1: ["C1"] },
    });
  });

  it("moves focus across a checkbox group with the arrow keys", async () => {
    renderControl(question("multiple_select", OPTIONS));
    const boxes = screen.getAllByRole("checkbox");

    await userEvent.tab();
    expect(document.activeElement).toBe(boxes[0]);

    await userEvent.keyboard("{ArrowDown}");
    expect(document.activeElement).toBe(boxes[1]);

    await userEvent.keyboard("{ArrowUp}");
    expect(document.activeElement).toBe(boxes[0]);
  });

  it("does not change any answer while arrowing through a checkbox group", async () => {
    // The distinction that matters: arrows navigate, Enter/Space commit. If
    // arrows also toggled, a respondent browsing their options would silently
    // check every box they passed.
    const onChange = renderControl(question("multiple_select", OPTIONS));
    await userEvent.tab();
    await userEvent.keyboard("{ArrowDown}{ArrowDown}{ArrowUp}");
    expect(onChange).not.toHaveBeenCalled();
  });

  it("keeps the native arrow behaviour of a radio group", async () => {
    // Native arrows move AND select for radios, so the group must NOT be
    // roving — one keypress should produce a selection, not just focus.
    const onChange = renderControl(question("single_select", OPTIONS));
    await userEvent.tab();
    await userEvent.keyboard("{ArrowDown}");
    expect(onChange).toHaveBeenCalledWith({ kind: "choice", choice: "Beta" });
  });

  it("lets a date be typed entirely from the keyboard", async () => {
    // `date` was reported alongside the choice types, but its native input is
    // already keyboard-operable — there is nothing to activate, the value is
    // typed. Enter has nothing to do here, and inventing something for it would
    // diverge from every other date field on the platform.
    const onChange = renderControl(question("date"));
    await userEvent.tab();
    await userEvent.keyboard("2026-08-11");
    expect(onChange).toHaveBeenCalled();
  });

  it("lets a number be typed entirely from the keyboard", async () => {
    const onChange = renderControl(question("number"));
    await userEvent.tab();
    await userEvent.keyboard("42");
    expect(onChange).toHaveBeenCalledWith({ kind: "text", text: "4" });
  });
});

/** Live wrapper: reordering is only observable across a real state update. */
function RankHarness() {
  const q = question("rank_order", OPTIONS);
  const [answer, setAnswer] = useState<PreviewAnswer>({
    kind: "ranking",
    ranking: ["Alpha", "Beta", "Gamma"],
  });
  return (
    <>
      <span id="prompt">{q.prompt}</span>
      <PreviewAnswerControl
        question={q}
        answer={answer}
        onChange={setAnswer}
        labelledBy="prompt"
        invalid={false}
      />
    </>
  );
}

describe("rank_order keyboard operability", () => {
  function order(): readonly string[] {
    return screen
      .getAllByRole("listitem")
      .map((li) => li.textContent ?? "")
      .map((text) => text.replace(/[^A-Za-z]/g, ""));
  }

  it("reorders with Enter on the move buttons", async () => {
    render(<RankHarness />);
    // Alpha's "move up" is disabled at position 1, so Tab lands on "move down".
    await userEvent.tab();
    await userEvent.keyboard("{Enter}");
    expect(order()[0]).toContain("Beta");
  });

  it("keeps focus on a control after a move, so the keyboard path continues", async () => {
    render(<RankHarness />);
    await userEvent.tab();
    await userEvent.keyboard("{Enter}");

    // The regression this pins: both buttons are natively disabled at the ends
    // of the list, so a move that lands an item at an end used to disable the
    // button that performed it, dropping focus to <body> and stranding a
    // keyboard respondent mid-question.
    expect(document.activeElement).not.toBe(document.body);
    expect(document.activeElement?.tagName).toBe("BUTTON");
  });

  it("survives a move that lands the item at the very end of the list", async () => {
    render(<RankHarness />);
    // By accessible name, not list position: the enabled-button order is
    // [Alpha-down, Beta-up, Beta-down, Gamma-up], which is easy to index wrong.
    // Beta's move-down sends it to the last position, disabling that button.
    const betaDown = screen.getByRole("button", {
      name: m.ask_survey_preview_rank_move_down({ item: "Beta" }),
    });
    betaDown.focus();
    await userEvent.keyboard("{Enter}");

    expect(document.activeElement).not.toBe(document.body);
    expect(order()[2]).toContain("Beta");
  });

  it("can move an item down and back up without ever losing focus", async () => {
    render(<RankHarness />);
    await userEvent.tab();
    await userEvent.keyboard("{Enter}");
    expect(document.activeElement).not.toBe(document.body);

    // A second Enter with no re-Tab only works if focus survived the first.
    await userEvent.keyboard("{Enter}");
    expect(document.activeElement).not.toBe(document.body);
    expect(order()[2]).toContain("Alpha");
  });
});

describe("rank_order with duplicate option labels", () => {
  // Nothing dedupes options, so an author or a CSV import can ship two identical
  // labels. Keyed by label, both rows shared one set of button handles and the
  // second row's ref callback overwrote the first, so focus restore could land on
  // the other row's button. Handles are keyed by POSITION for exactly this.
  function DupHarness() {
    const q = question("rank_order", { options: ["Same", "Same", "Other"] });
    const [answer, setAnswer] = useState<PreviewAnswer>({
      kind: "ranking",
      ranking: ["Same", "Same", "Other"],
    });
    return (
      <>
        <span id="prompt">{q.prompt}</span>
        <PreviewAnswerControl
          question={q}
          answer={answer}
          onChange={setAnswer}
          labelledBy="prompt"
          invalid={false}
        />
      </>
    );
  }

  it("renders one row per duplicate rather than collapsing them", () => {
    render(<DupHarness />);
    expect(screen.getAllByRole("listitem")).toHaveLength(3);
  });

  it("keeps focus on a real control after moving a duplicate-labelled item", async () => {
    render(<DupHarness />);
    await userEvent.tab();
    await userEvent.keyboard("{Enter}");

    expect(document.activeElement).not.toBe(document.body);
    expect(document.activeElement?.tagName).toBe("BUTTON");
  });

  it("moves only ONE of the two identical items", async () => {
    render(<DupHarness />);
    await userEvent.tab();
    await userEvent.keyboard("{Enter}");

    // "Other" was last; moving row 1 down must not disturb it, and both "Same"
    // rows must survive — a collapsed identity would drop or duplicate a row.
    const rows = screen
      .getAllByRole("listitem")
      .map((li) => (li.textContent ?? "").replace(/[^A-Za-z]/g, ""));
    expect(rows).toHaveLength(3);
    expect(rows.filter((r) => r.startsWith("Same"))).toHaveLength(2);
  });
});



