/**
 * PreviewAnswerControl tests (#1284) — the respondent-side control for each of
 * the proto's canonical 10 `QuestionType`s.
 *
 * These controls are GENUINELY INTERACTIVE, which is the whole difference from
 * `editor/QuestionAnswerPreview.tsx`'s deliberately inert shapes. So the
 * coverage that matters is: does each type render a real, correctly-roled
 * control, and does interacting with it report the right answer shape back.
 */

import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { PreviewAnswerControl } from "../PreviewAnswerControl";
import { initialAnswer } from "../../../lib/previewAnswers";
import type { PreviewAnswer } from "../../../lib/previewAnswers";
import type { QuestionDTO, QuestionType } from "../../../api/questions";

// Held in constants, not written inline: `react/jsx-no-literals` (noStrings)
// is the i18n leak guard, and it flags a bare string child even in a test.
const ERROR_TEXT = "bad";

function question(
  type: QuestionType,
  overrides: Partial<QuestionDTO> = {},
): QuestionDTO {
  return {
    id: "q1",
    questionType: type,
    prompt: "How was it?",
    position: 0,
    required: false,
    config: {},
    branches: [],
    ...overrides,
  };
}

function renderControl(
  q: QuestionDTO,
  answer: PreviewAnswer = initialAnswer(q),
  opts: { invalid?: boolean } = {},
) {
  const onChange = vi.fn();
  render(
    <>
      <span id="prompt">{q.prompt}</span>
      <PreviewAnswerControl
        question={q}
        answer={answer}
        onChange={onChange}
        labelledBy="prompt"
        errorId={opts.invalid === true ? "err" : undefined}
        invalid={opts.invalid ?? false}
      />
      <span id="err">{ERROR_TEXT}</span>
    </>,
  );
  return onChange;
}

describe("PreviewAnswerControl — single_select / yes_no / true_false", () => {
  const q = question("single_select", { config: { options: ["Good", "Bad"] } });

  it("renders a radiogroup with one radio per option", () => {
