/**
 * PreviewMatrixGrid tests (#1284) — the respondent-side matrix control.
 *
 * The table semantics are the point: a respondent facing an unlabelled control
 * in the middle of a grid can only tell what it means from its row and column
 * headers, so `scope` and the header structure are asserted directly rather
 * than inferred from the rendered text.
 */

import { render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { PreviewMatrixGrid } from "../PreviewMatrixGrid";

const ROWS = ["Speed", "Price"] as const;
const COLUMNS = ["Low", "High"] as const;

function renderGrid(
  overrides: {
    allowMultiple?: boolean;
    selected?: Readonly<Record<string, readonly string[]>>;
  } = {},
) {
  const onToggle = vi.fn();
  render(
    <PreviewMatrixGrid
      questionId="q1"
      rows={[...ROWS]}
      columns={[...COLUMNS]}
      allowMultiple={overrides.allowMultiple ?? false}
      selected={overrides.selected ?? {}}
      onToggle={onToggle}
    />,
  );
  return onToggle;
}

describe("PreviewMatrixGrid", () => {
  it("renders a real table with column and row headers", () => {
    renderGrid();

    const table = screen.getByRole("table");
    for (const column of COLUMNS) {
      expect(
        within(table).getByRole("columnheader", { name: column }),
      ).toHaveAttribute("scope", "col");
    }
    for (const row of ROWS) {
      expect(within(table).getByRole("rowheader", { name: row })).toHaveAttribute(
        "scope",
        "row",
      );
    }
  });

  it("captions a single-select matrix with the one-per-row rule", () => {
    renderGrid();
    expect(
      screen.getByText(m.ask_survey_preview_matrix_caption_single()),
    ).toBeInTheDocument();
  });

  it("captions a multi-select matrix with the one-or-more rule", () => {
    renderGrid({ allowMultiple: true });
    expect(
      screen.getByText(m.ask_survey_preview_matrix_caption_multiple()),
    ).toBeInTheDocument();
  });

  it("renders radios when only one column per row is allowed", () => {
    renderGrid();

    expect(screen.getAllByRole("radio")).toHaveLength(ROWS.length * COLUMNS.length);
    expect(screen.queryAllByRole("checkbox")).toHaveLength(0);
  });

  it("renders checkboxes when several columns per row are allowed", () => {
    renderGrid({ allowMultiple: true });

    expect(screen.getAllByRole("checkbox")).toHaveLength(
      ROWS.length * COLUMNS.length,
    );
    expect(screen.queryAllByRole("radio")).toHaveLength(0);
  });

  it("groups each row's radios under their own name so one row's choice is exclusive", () => {
    // Without a per-row `name`, selecting a column in one row would clear every
    // other row's selection.
    renderGrid();

    const speedLow = screen.getByRole("radio", {
      name: m.ask_survey_editor_cfg_matrix_cell_aria({ row: "Speed", column: "Low" }),
    });
    const priceLow = screen.getByRole("radio", {
      name: m.ask_survey_editor_cfg_matrix_cell_aria({ row: "Price", column: "Low" }),
    });

    expect(speedLow.getAttribute("name")).not.toBe(priceLow.getAttribute("name"));
  });

  it("names every cell by its row and column", () => {
    renderGrid();

    expect(
      screen.getByRole("radio", {
        name: m.ask_survey_editor_cfg_matrix_cell_aria({
          row: "Price",
          column: "High",
        }),
      }),
    ).toBeInTheDocument();
  });

  it("reflects the current selection", () => {
    renderGrid({ selected: { Speed: ["High"] } });

    expect(
      screen.getByRole("radio", {
        name: m.ask_survey_editor_cfg_matrix_cell_aria({
          row: "Speed",
          column: "High",
        }),
      }),
    ).toBeChecked();
    expect(
      screen.getByRole("radio", {
        name: m.ask_survey_editor_cfg_matrix_cell_aria({
          row: "Speed",
          column: "Low",
        }),
      }),
    ).not.toBeChecked();
  });

  it("reports a clicked cell as (row, column)", async () => {
    const onToggle = renderGrid();

    await userEvent.click(
      screen.getByRole("radio", {
        name: m.ask_survey_editor_cfg_matrix_cell_aria({
          row: "Price",
          column: "High",
        }),
      }),
    );

    expect(onToggle).toHaveBeenCalledWith("Price", "High");
  });

  it("uses a round control for single-select and a rounded square for multi", () => {
    // design.md §11.5's shape rule — the affordance has to tell a respondent
    // whether they may pick more than one, before they try.
    const { unmount } = render(
      <PreviewMatrixGrid
        questionId="q1"
        rows={["Speed"]}
        columns={["Low"]}
        allowMultiple={false}
        selected={{}}
        onToggle={vi.fn()}
      />,
    );
    expect(screen.getByRole("radio").className).toContain("rounded-pill");
    unmount();

    render(
      <PreviewMatrixGrid
        questionId="q1"
        rows={["Speed"]}
        columns={["Low"]}
        allowMultiple
        selected={{}}
        onToggle={vi.fn()}
      />,
    );
    expect(screen.getByRole("checkbox").className).toContain("rounded-md");
  });

  it("scopes horizontal overflow to itself so a wide matrix doesn't scroll the page", () => {
    renderGrid();

    const wrapper = screen.getByRole("table").parentElement;
    expect(wrapper?.className).toContain("overflow-x-auto");
  });
});


