/**
 * PreviewQuestionCard tests (#1284) — one question as a respondent sees it.
 *
 * `validationMessage` is exported and tested directly: it is the only mapping
 * from `lib/previewAnswers.ts`'s validation CODES to localized copy, so a code
 * added there without a branch here would otherwise surface as a blank error
 * rather than a compile failure in a test run.
 */

import { render, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { PreviewQuestionCard, validationMessage } from "../PreviewQuestionCard";
import { initialAnswer } from "../../../lib/previewAnswers";
import type { PreviewValidationError } from "../../../lib/previewAnswers";
import type { QuestionDTO, QuestionType } from "../../../api/questions";

function question(
  type: QuestionType = "free_text",
  overrides: Partial<QuestionDTO> = {},
): QuestionDTO {
  return {
    id: "q1",
    questionType: type,
    prompt: "How likely are you to recommend us?",
    position: 0,
    required: false,
    config: {},
    branches: [],
    ...overrides,
  };
}

function renderCard(
  q: QuestionDTO = question(),
  opts: { number?: number; error?: PreviewValidationError } = {},
) {
  const onChange = vi.fn();
  render(
    <ol>
      <PreviewQuestionCard
        question={q}
        number={opts.number ?? 1}
        answer={initialAnswer(q)}
        onChange={onChange}
        error={opts.error}
      />
    </ol>,
  );
  return onChange;
}

describe("PreviewQuestionCard", () => {
  it("renders the prompt with its 1-based number", () => {
    renderCard(question(), { number: 3 });

    expect(
      screen.getByText("How likely are you to recommend us?"),
    ).toBeInTheDocument();
    expect(screen.getByText("3.")).toBeInTheDocument();
  });

  it("marks a required question with TEXT, never colour or a bare asterisk", () => {
    // design.md §0 — "never colour alone" applies to a respondent surface too,
    // and an unexplained `*` is exactly what makes required fields ambiguous.
    renderCard(question("free_text", { required: true }));

    expect(
      screen.getByText(m.ask_survey_detail_question_required_label()),
    ).toBeInTheDocument();
  });

  it("omits the required marker for an optional question", () => {
    renderCard(question());

    expect(
      screen.queryByText(m.ask_survey_detail_question_required_label()),
    ).not.toBeInTheDocument();
  });

  it("renders the author's help text when present", () => {
    renderCard(question("free_text", { config: { help_text: "Be honest" } }));
    expect(screen.getByText("Be honest")).toBeInTheDocument();
  });

  it("renders no help paragraph when help text is empty", () => {
    renderCard(question("free_text", { config: { help_text: "" } }));
    expect(screen.queryByText("Be honest")).not.toBeInTheDocument();
  });

  it("names the control from the prompt, number and required marker included", () => {
    // The labelling element wraps the number and the Required marker as well as
    // the prompt, so the computed accessible name is "3. <prompt> Required".
    // That is deliberate: a screen-reader user hears which question they are on
    // and whether it must be answered, without having to explore the card.
    renderCard(question("free_text", { required: true }), { number: 3 });

    const control = screen.getByLabelText(/How likely are you to recommend us\?/);
    expect(control).toBeInTheDocument();

    const name =
      document.getElementById(
        control.getAttribute("aria-labelledby") ?? "",
      )?.textContent ?? "";
    expect(name).toContain("3.");
    expect(name).toContain("How likely are you to recommend us?");
    expect(name).toContain(m.ask_survey_detail_question_required_label());
  });

  it("carries a data-question-id so the route can focus the first invalid card", () => {
    renderCard();
    expect(screen.getByRole("listitem")).toHaveAttribute("data-question-id", "q1");
  });

  it("renders a validation error as an alert and links it to the control", () => {
    renderCard(question(), { error: { code: "required" } });

    const alert = screen.getByRole("alert");
    expect(alert).toHaveTextContent(m.ask_survey_preview_required_error());
    expect(screen.getByRole("textbox")).toHaveAttribute(
      "aria-describedby",
      alert.id,
    );
  });

  it("renders no alert when the question is valid", () => {
    renderCard();
    expect(screen.queryByRole("alert")).not.toBeInTheDocument();
  });
});

describe("validationMessage", () => {
  it.each([
    [{ code: "required" } as const, () => m.ask_survey_preview_required_error()],
    [
      { code: "text_too_short", min: 5 } as const,
      () => m.ask_survey_preview_text_too_short({ min: 5 }),
    ],
    [
      { code: "text_too_long", max: 9 } as const,
      () => m.ask_survey_preview_text_too_long({ max: 9 }),
    ],
    [
      { code: "number_invalid" } as const,
      () => m.ask_survey_preview_number_invalid(),
    ],
    [
      { code: "number_out_of_range", min: 1, max: 10 } as const,
      () => m.ask_survey_preview_number_out_of_range({ min: 1, max: 10 }),
    ],
    [
      { code: "date_out_of_range", min: "2026-01-01", max: "2026-12-31" } as const,
      () =>
        m.ask_survey_preview_date_out_of_range({
          min: "2026-01-01",
          max: "2026-12-31",
        }),
    ],
    // The one-sided bounds. Their own messages exist because the range copy
    // names BOTH ends — "between 5 and undefined" is what the alternative
    // would have rendered.
    [
      { code: "number_too_small", min: 18 } as const,
      () => m.ask_survey_preview_number_too_small({ min: 18 }),
    ],
    [
      { code: "number_too_large", max: 10 } as const,
      () => m.ask_survey_preview_number_too_large({ max: 10 }),
    ],
    [
      { code: "date_too_early", min: "2026-01-01" } as const,
      () => m.ask_survey_preview_date_too_early({ min: "2026-01-01" }),
    ],
    [
      { code: "date_too_late", max: "2026-12-31" } as const,
      () => m.ask_survey_preview_date_too_late({ max: "2026-12-31" }),
    ],
  ])("maps %o to its localized message", (error, expected) => {
    expect(validationMessage(error)).toBe(expected());
  });

  it("interpolates the bound into the message rather than hardcoding it", () => {
    expect(validationMessage({ code: "text_too_short", min: 42 })).toContain("42");
  });
});


