/**
 * PreviewRankList tests (#1284) — the respondent-side rank_order control.
 *
 * Reordering is by explicit Up/Down buttons rather than drag-and-drop, so the
 * keyboard path IS the primary path and is tested as such: every assertion here
 * runs through real clicks/keys on named buttons, with no dnd-kit sensor to
 * simulate and no jsdom layout dependency (dnd-kit's keyboard sensor builds its
 * own candidate list independently of pointer collision detection, so the two
 * have to be verified separately — a cost this control does not pay).
 */

import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { PreviewRankList } from "../PreviewRankList";

// See PreviewAnswerControl.test.tsx — react/jsx-no-literals bans inline
// string children, so the labelling text lives in a constant.
const PROMPT = "Rank these";

function renderList(
  ranking: readonly string[] = ["Speed", "Price", "Support"],
  onChange = vi.fn(),
) {
  render(
    <>
      <span id="prompt">{PROMPT}</span>
      <PreviewRankList ranking={ranking} onChange={onChange} labelledBy="prompt" />
    </>,
  );
  return onChange;
}

describe("PreviewRankList", () => {
  it("renders every item with its 1-based position", () => {
    renderList();

    const items = screen.getAllByRole("listitem");
    expect(items).toHaveLength(3);
    expect(items[0]).toHaveTextContent("Speed");
    expect(items[2]).toHaveTextContent("Support");
  });

  it("shows the ranking hint", () => {
    renderList();
    expect(screen.getByText(m.ask_survey_preview_rank_hint())).toBeInTheDocument();
  });

  it("labels the list with its question prompt", () => {
    renderList();
    expect(screen.getByRole("list")).toHaveAttribute("aria-labelledby", "prompt");
  });

  it("exposes each item's position as text for screen readers", () => {
    renderList();

    expect(
      screen.getByText(m.ask_survey_preview_rank_position({ position: 2, total: 3 })),
    ).toBeInTheDocument();
  });

  it("names each arrow after the item it moves", () => {
    renderList();

    expect(
      screen.getByRole("button", {
        name: m.ask_survey_preview_rank_move_up({ item: "Price" }),
      }),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("button", {
        name: m.ask_survey_preview_rank_move_down({ item: "Price" }),
      }),
    ).toBeInTheDocument();
  });

  it("moves an item up", async () => {
    const onChange = renderList();

    await userEvent.click(
      screen.getByRole("button", {
        name: m.ask_survey_preview_rank_move_up({ item: "Price" }),
      }),
    );

    expect(onChange).toHaveBeenCalledWith(["Price", "Speed", "Support"]);
  });

  it("moves an item down", async () => {
    const onChange = renderList();

    await userEvent.click(
      screen.getByRole("button", {
        name: m.ask_survey_preview_rank_move_down({ item: "Speed" }),
      }),
    );

    expect(onChange).toHaveBeenCalledWith(["Price", "Speed", "Support"]);
  });

  it("is fully operable from the keyboard", async () => {
    const onChange = renderList();

    const down = screen.getByRole("button", {
      name: m.ask_survey_preview_rank_move_down({ item: "Speed" }),
    });
    down.focus();
    await userEvent.keyboard("{Enter}");

    expect(onChange).toHaveBeenCalledWith(["Price", "Speed", "Support"]);
  });

  it("disables Up on the first item and Down on the last", () => {
    renderList();

    expect(
      screen.getByRole("button", {
        name: m.ask_survey_preview_rank_move_up({ item: "Speed" }),
      }),
    ).toBeDisabled();
    expect(
      screen.getByRole("button", {
        name: m.ask_survey_preview_rank_move_down({ item: "Support" }),
      }),
    ).toBeDisabled();
  });

  it("cannot request a no-op move: a lone item has both arrows disabled", async () => {
    // This is why the component needs no `next !== ranking` guard — the disabled
    // attribute is the single mechanism preventing an out-of-range move, so the
    // handler is never even reached.
    const onChange = renderList(["Only"]);

    const up = screen.getByRole("button", {
      name: m.ask_survey_preview_rank_move_up({ item: "Only" }),
    });
    const down = screen.getByRole("button", {
      name: m.ask_survey_preview_rank_move_down({ item: "Only" }),
    });
    expect(up).toBeDisabled();
    expect(down).toBeDisabled();

    await userEvent.click(up);
    await userEvent.click(down);

    expect(onChange).not.toHaveBeenCalled();
  });

  it("renders nothing but the hint for an empty ranking", () => {
    renderList([]);

    expect(screen.queryAllByRole("listitem")).toHaveLength(0);
    expect(screen.queryAllByRole("button")).toHaveLength(0);
  });
});


